A.aJC=new B.a("titulo_seccion","18b. Fiesta de un Santo")
A.bGZ=new B.a("celebrante","Dios, nuestro Padre, que nos ha congregado para celebrar hoy la fiesta de san N., [Patrono de nuestra comunidad N. parroquial, diocesana, nacional ], los bendiga, proteja y confirme en su paz.")
A.bC1=new B.a("celebrante","Cristo, el Se\xf1or, que ha manifestado en san N. la fuerza renovadora del misterio pascual, los haga aut\xe9nticos testigos de su Evangelio.")
A.caj=new B.a("celebrante","El Esp\xedritu Santo, que en san N. nos ha ofrecido un ejemplo de caridad evang\xe9lica, les conceda la gracia de acrecentar en la Iglesia la verdadera comuni\xf3n de fe y amor.")
A.d9K=s([A.aJC,A.bGZ,A.T,A.bC1,A.T,A.caj,A.T,A.dW,A.T],t.W)
A.bPp=new B.a("titulo_seccion","III. Otras bendiciones\n19. En la dedicaci\xf3n de una iglesia")
A.buy=new B.a("celebrante","Dios, Se\xf1or del cielo y de la tierra que los ha reunido hoy para la dedicaci\xf3n de esta iglesia los colme con la abundancia de su bendici\xf3n.")
A.bpW=new B.a("celebrante","\xc9l, que quiso congregar por medio de su Hijo \xfanico a todos sus hijos dispersos, les conceda ser templo y morada del Esp\xedritu Santo.")
A.RK=new B.a("celebrante","\xc9l, que los ha purificado habite en ustedes, y les conceda alcanzar, junto con todos los santos, la felicidad eterna,")
A.aGQ=new B.a("celebrante","Y la bendici\xf3n de Dios todopoderoso, Padre, Hijo + y Esp\xedritu Santo, descienda sobre ustedes y permanezca para siempre.")
A.cAX=s([A.bPp,A.buy,A.T,A.bpW,A.T,A.RK,A.T,A.aGQ,A.T],t.W)
A.aVp=new B.a("titulo_seccion","20. Celebraciones de difuntos")
A.b_X=new B.a("celebrante","El Dios de todo consuelo, que por su bondad infinita cre\xf3 al hombre y por la Resurrecci\xf3n de su Hijo, concedi\xf3 a los creyentes la esperanza en la resurrecci\xf3n los bendiga.")
A.bEQ=new B.a("celebrante","Nos conceda el perd\xf3n de los pecados a los que a\xfan vivimos, y conduzca a todos nuestros hermanos difuntos al lugar de la luz y de la paz.")
A.cbp=new B.a("celebrante","Para que todos vivamos eternamente con Cristo, a quien proclamamos resucitado de entre los muertos.")
A.diz=s([A.aVp,A.b_X,A.T,A.bEQ,A.T,A.cbp,A.T,A.dW,A.T],t.W)
