A.e3K={"I. Celebraci\xf3n de los sacramentos de la iniciaci\xf3n cristiana":0,"II. Celebraci\xf3n de la Unci\xf3n de los Enfermos":1,"III. Celebraci\xf3n del Vi\xe1tico":2,"IV. Celebraci\xf3n del Orden Sagrado":3,"V. Celebraci\xf3n del Matrimonio":4,"VI. Bendici\xf3n de un Abad o de una Abadesa":5,"VII. Consagraci\xf3n de V\xedrgenes":6,"VIII. Profesi\xf3n Religiosa":7,"IX. Instituci\xf3n de Lectores y Ac\xf3litos":8,"X. Dedicaci\xf3n de una Iglesia y de un Altar":9}
